// 1. Hole die Query-Parameter vom Webhook (eingehende Daten)
const query = $input.all()[0].json.query || {};

// 2. Hier DEIN Token eintragen (muss exakt gleich sein wie bei Meta)
const VERIFY_TOKEN = "DEIN_VERIFY_TOKEN"; 

// 3. Daten aus der Meta-Anfrage extrahieren
const mode = query["hub.mode"];
const token = query["hub.verify_token"];
const challenge = query["hub.challenge"];

// 4. Überprüfen, ob Token übereinstimmen
if (mode === "subscribe" && token === VERIFY_TOKEN) {
  // WICHTIG: Wir geben die "challenge" zurück, damit der "Respond to Webhook" Node sie senden kann
  return {
    json: {
      body: challenge, 
      status: 200
    }
  };
} else {
  // Falls das Token falsch ist
  return {
    json: {
      body: "Verification failed",
      status: 403
    }
  };
}
